package main

import (
	"strings"
	"testing"
)

func TestProbeListenAddr(t *testing.T) {
	cases := []struct {
		env    string
		want   string
		errMsg string
	}{
		{env: "", want: ":8080"},
		{env: ":9090", want: ":9090"},
		{env: "localhost:8081", want: "localhost:8081"},
		{env: "0.0.0.0:8082", want: "0.0.0.0:8082"},
		{env: "no-colon", errMsg: "ADDR"},
		{env: "host:notaport", errMsg: "ADDR"},
		{env: "host:", errMsg: "ADDR"},
	}
	for _, tc := range cases {
		value := tc.env
		getenv := func(string) string { return value }
		addr, err := listenAddr(getenv)
		if tc.errMsg != "" {
			if err == nil {
				t.Fatalf("ADDR=%q: want error, got %q", tc.env, addr)
			}
			if !strings.Contains(err.Error(), tc.errMsg) {
				t.Fatalf("ADDR=%q: error %q must mention ADDR", tc.env, err.Error())
			}
			continue
		}
		if err != nil {
			t.Fatalf("ADDR=%q: unexpected error %v", tc.env, err)
		}
		if addr != tc.want {
			t.Fatalf("ADDR=%q: addr = %q, want %q", tc.env, addr, tc.want)
		}
	}
	// Unset variable (getenv returns empty) is the default case; a nil-ish
	// lookup for a DIFFERENT variable must not matter.
	getenv := func(key string) string {
		if key == "OTHER" {
			return "x"
		}
		return ""
	}
	if addr, err := listenAddr(getenv); err != nil || addr != ":8080" {
		t.Fatalf("unset ADDR: %q %v", addr, err)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_addr_test.go ; exit $rc

